$decision=@{};$validGeneralizability=@('HIGH','CONDITIONAL','LOW','NONE','N/A');$validTemplateStatus=@('VALIDATED','VALIDATED_WITH_CONDITIONS','REJECTED','REQUIRES_MORE_REPRESENTATIVES','HUMAN_REVIEW_REQUIRED','N/A');$validIndividualRoute=@('MODEL_REPAIR_PROPOSAL_ACCEPTABLE_FOR_HUMAN_QA','HUMAN_ADJUDICATION_REQUIRED','NO_REPAIR','ABSTAIN','N/A')
