foreach($r in $input){$p=$decision[$r.RECORD_ID];if(-not $p){throw "No decision for $($r.RECORD_ID)"};$out.Add([pscustomobject][ordered]@{CASE_ID=$r.CASE_ID;RECORD_ID=$r.RECORD_ID;BATCH_ID=$r.BATCH_ID;REVIEW_TYPE=$r.REVIEW_SCOPE;SOURCE_TYPE=$r.SOURCE_TYPE;SOURCE_REFERENCE=$r.SOURCE_REFERENCE;INPUT_HASH=$r.INPUT_HASH;MODEL_REQUESTED='GPT-5.6 Terra High';MODEL_RESEARCHER_SELECTED='GPT-5.6 Terra High';MODEL_RUNTIME_VARIANT='MODEL_VARIANT_NOT_EXPOSED';RUN_TIMESTAMP=$now;ADVANCED_DEFECT_PRESENT=$p[1];PROPOSITION_ANCHOR_CONFIDENCE=$p[2];ACTOR_CORRECT=$p[3];ACTION_CORRECT=$p[4];OBJECT_CORRECT=$p[5];COUNTERPART_CORRECT=$p[6];RECIPIENT_CORRECT=$p[7];PROPOSED_ACTOR=$p[9];PROPOSED_ACTION=$p[10];PROPOSED_OBJECT=$p[11];PROPOSED_COUNTERPART=$p[12];PROPOSED_RECIPIENT=$p[13];PROPOSED_CONTEXT_MODIFIER=$p[14];RELATIONAL_FIELD_DIFFERENTIATION=$p[8];RELATIONAL_ENTITY=if($p[8] -in @('COUNTERPART_ONLY','RECIPIENT_ONLY')){if($p[12] -ne 'NONE_EXPLICIT'){$p[12]}else{$p[13]}}else{'NONE_EXPLICIT'};RELATIONAL_ROLE_RATIONALE=$p[15];ADVANCED_REASONING_NOTE=$p[15];TEMPLATE_GENERALIZABILITY=$p[16];FAMILY_TEMPLATE_STATUS=$p[17];REPAIR_TEMPLATE=if($p[17] -eq 'VALIDATED_WITH_CONDITIONS'){'Apply only where the frozen source has the stated matrix predicate and the existing field demonstrably substitutes it, promotes a non-actor prepositional phrase, or drops an explicit addressee.'}else{''};TEMPLATE_APPLICATION_CONDITIONS=if($p[17] -eq 'VALIDATED_WITH_CONDITIONS'){'Verify the same proposition anchor, source wording, clause structure and relational role for every candidate; do not apply across coordinated or embedded propositions.'}else{''};CASE_ROUTE_AFTER_REVIEW=$p[18]})}
