$templates=[System.Collections.Generic.List[object]]::new();$individuals=[System.Collections.Generic.List[object]]::new()
foreach($o in $out){$manifestRow=$manifest|Where-Object RECORD_ID -eq $o.RECORD_ID|Select-Object -First 1;if($manifestRow.REVIEW_TYPE -eq 'TEMPLATE_REPRESENTATIVE'){[void]$templates.Add($o)}elseif($manifestRow.REVIEW_TYPE -eq 'INDIVIDUAL_ADVANCED_CASE'){[void]$individuals.Add($o)}}
$templates|Select-Object CASE_ID,RECORD_ID,BATCH_ID,SOURCE_REFERENCE,ADVANCED_DEFECT_PRESENT,PROPOSITION_ANCHOR_CONFIDENCE,TEMPLATE_GENERALIZABILITY,FAMILY_TEMPLATE_STATUS,REPAIR_TEMPLATE,TEMPLATE_APPLICATION_CONDITIONS,ADVANCED_REASONING_NOTE|Export-Csv (Join-Path $b1 'R4_2E_B1_FAMILY_TEMPLATE_VALIDATION.csv') -NoTypeInformation -Encoding UTF8
$individuals|Export-Csv (Join-Path $b1 'R4_2E_B1_INDIVIDUAL_CASE_DECISIONS.csv') -NoTypeInformation -Encoding UTF8
