$log=@(Import-Csv (Join-Path $b1 'R4_2E_B1_BATCH_RUN_LOG.csv') -Encoding UTF8);foreach($x in $log){if($x.BATCH_ID -eq 'B1-01'){$x.RUN_VERSION='v2_SCHEMA_CORRECTED';$x.OUTPUT_HASH=$outputHash;$x.END_STATUS='R4_2E_B1_BATCH_01_COMPLETE_PENDING_CONTROL_UNBLINDING';$x.COMPLETION_STATUS='COMPLETE';$x.RUN_TIMESTAMP=$now}};$log|Export-Csv (Join-Path $b1 'R4_2E_B1_BATCH_RUN_LOG.csv') -NoTypeInformation -Encoding UTF8
